(()=>{'use strict';const KEY='form-fuel-wellness-v1',today=()=>CalendarCore.dayKey(new Date());let db={schema:1,targets:[],days:{}},readError=false;try{const raw=localStorage.getItem(KEY);if(raw){const x=JSON.parse(raw);if(x.schema!==1||!Array.isArray(x.targets)||!x.days||typeof x.days!=='object')throw Error();db=x;}}catch{readError=true;}
const host=document.createElement('div');host.id='wellnessProgress';host.innerHTML='<div class="wellness-heading"><div><p class="eyebrow">ACTIVITY & RECOVERY</p><h3>Move well. Recover better.</h3></div><button class="text-button" id="wellnessTargets" type="button">Set targets ↗</button></div><div id="wellnessBars" class="macro-progress"></div><div class="wellness-actions"><button type="button" class="secondary" id="logActivity">Log workout ↗</button><button type="button" class="secondary" id="logSleep">Log sleep ↗</button></div><p class="tiny">Burn comes from completed workouts and stays separate from your food target. Sleep is logged against the day you wake up. Goals are chosen by you.</p>';document.querySelector('.nutrition-content').append(host);
function persist(next){if(readError){toast('Wellness storage could not be read. Existing data was left untouched.');return false;}try{localStorage.setItem(KEY,JSON.stringify(next));db=next;render();return true;}catch{toast('Wellness changes could not be saved in this browser.');return false;}}
function goals(date){return CalendarCore.versionAt(db.targets,date)||null;}
function burn(date){try{const log=JSON.parse(localStorage.getItem('form-fuel-calendar-v1')||'{}').logs?.[date];return {value:log?log.burn:0,recorded:!!log};}catch{return {value:null,recorded:false};}}
function fmt(n){return Number(n).toLocaleString(undefined,{maximumFractionDigits:1});}
function bar(key,label,value,target,unit,known){const fraction=target&&known?Math.min(100,value/target*100):0,reached=target&&known&&value>=target;const icon=key==='burn'?'<path d="M13 3c1 6-5 6-3 11l4-4c6 5 4 11-2 11-7 0-9-8-5-12 0 4 3 4 3 4-1-5 3-10 3-10Z"/>':'<path d="M19 15A8 8 0 0 1 9 5a8.5 8.5 0 1 0 10 10Z"/><path d="M17 3v4m-2-2h4"/>';return '<div class="macro-card macro-'+key+'"><div class="macro-fill" style="width:'+fraction+'%"></div><span class="macro-icon" aria-hidden="true"><svg viewBox="0 0 24 24">'+icon+'</svg></span><div class="macro-copy"><h4>'+label+'</h4><div class="macro-amount"><strong>'+(known?fmt(value):'—')+'</strong> <span>/ '+(target?fmt(target):'—')+' '+unit+'</span></div><p>'+(!known?(key==='sleep'?'No sleep logged':'Burn unavailable — edit your workout'):!target?'Set your daily goal':reached?'Daily goal reached ✓':fmt(Math.max(0,target-value))+' '+unit+' to your goal')+'</p></div><span class="macro-percent">'+(target&&known?Math.round(value/target*100)+'%':'—')+'</span><div class="macro-accessible" role="progressbar" aria-label="'+label+' daily goal" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+Math.round(fraction)+'" aria-valuetext="'+(known?fmt(value)+' '+unit:'Not logged')+'; target '+(target?fmt(target)+' '+unit:'not set')+'"></div></div>';}
function render(){const previous=[...host.querySelectorAll('.macro-fill')].map(b=>b.style.width);const date=window.fuelDay?.()||today(),g=goals(date),b=burn(date),sleep=db.days[date]?.sleep;host.querySelector('#wellnessBars').innerHTML=bar('burn','Workout burn',b.value,g?.burn,'kcal',b.value!==null)+bar('sleep','Sleep',sleep,g?.sleep,'hours',Number.isFinite(sleep));host.querySelectorAll('.macro-fill').forEach((b,i)=>{const target=b.style.width;b.style.width=previous[i]||'0%';requestAnimationFrame(()=>requestAnimationFrame(()=>b.style.width=target));});host.querySelector('#wellnessTargets').textContent=g?'Edit targets ↗':'Set targets ↗';renderCalendar();}
function renderCalendar(){const date=window.WorkoutCalendar?.selectedDate();const detail=document.querySelector('#calendarDetail'),burnCard=detail?.querySelector('.calendar-burn');if(!date||!burnCard)return;detail.querySelector('.wellness-calendar')?.remove();burnCard.querySelector('.wellness-burn-goal')?.remove();const g=goals(date),b=burn(date),sleep=db.days[date]?.sleep;const p=document.createElement('p');p.className='wellness-burn-goal';p.textContent=g?'Burn goal: '+fmt(g.burn)+' kcal · '+(b.value===null?'No burn estimate':b.value>=g.burn?'Goal reached':'Goal not yet reached'):'No burn goal saved for this day.';burnCard.append(p);const card=document.createElement('div');card.className='wellness-calendar';card.innerHTML='<h4>Sleep & recovery</h4>'+bar('sleep','Sleep',sleep,g?.sleep,'hours',Number.isFinite(sleep))+(date<=today()?'<button type="button" class="text-button">'+(Number.isFinite(sleep)?'Edit sleep':'Log sleep')+' for this day ↗</button>':'');card.querySelector('button')?.addEventListener('click',()=>openSleep(date));burnCard.after(card);}
const targetDialog=document.createElement('dialog');targetDialog.id='wellnessTargetDialog';targetDialog.setAttribute('aria-labelledby','wellnessTargetTitle');targetDialog.innerHTML='<form><div class="dialog-heading"><div><p class="eyebrow">ACTIVITY & RECOVERY GOALS</p><h2 id="wellnessTargetTitle">Your daily targets</h2></div><button type="button" class="close" aria-label="Close wellness targets">×</button></div><p class="muted">Choose goals that fit your training and recovery needs. These starting values are editable.</p><div class="form-grid"><label>Workout burn target (kcal)<input name="burn" type="number" min="1" max="3000" step="1" required></label><label>Sleep target (hours)<input name="sleep" type="number" min="1" max="24" step="0.25" required></label></div><p class="tiny">Applies from today. Previous days keep the goals saved for those dates. Burn is workout activity, not total daily calories burned.</p><button type="submit" class="primary full">Save daily targets ↗</button></form>';document.body.append(targetDialog);const tf=targetDialog.querySelector('form');targetDialog.querySelector('.close').onclick=()=>targetDialog.close();host.querySelector('#wellnessTargets').onclick=()=>{const g=goals(today());tf.elements.burn.value=g?.burn||300;tf.elements.sleep.value=g?.sleep||8;targetDialog.showModal();};tf.onsubmit=e=>{e.preventDefault();if(!tf.reportValidity())return;const next=structuredClone(db);next.targets=next.targets.filter(t=>t.from!==today());next.targets.push({from:today(),burn:Number(tf.elements.burn.value),sleep:Number(tf.elements.sleep.value)});if(persist(next)){targetDialog.close();toast('Activity and sleep targets saved from today.');}};
const sleepDialog=document.createElement('dialog');sleepDialog.id='sleepLogDialog';sleepDialog.setAttribute('aria-labelledby','sleepLogTitle');sleepDialog.innerHTML='<form><div class="dialog-heading"><div><p class="eyebrow">RECOVERY STARTS HERE</p><h2 id="sleepLogTitle">Log your sleep</h2></div><button type="button" class="close" aria-label="Close sleep log">×</button></div><label>Wake-up date<input name="date" type="date" required></label><label>Hours slept<input name="hours" type="number" min="0" max="24" step="0.25" placeholder="e.g. 7.5" required></label><p class="tiny">Enter total sleep for the night ending on this date. Saving again updates this day’s record.</p><button type="submit" class="primary full">Save sleep ↗</button><button type="button" class="text-button" id="clearSleep">Remove this sleep entry</button></form>';document.body.append(sleepDialog);const sf=sleepDialog.querySelector('form');sleepDialog.querySelector('.close').onclick=()=>sleepDialog.close();function fillSleep(){sf.elements.hours.value=db.days[sf.elements.date.value]?.sleep??'';sleepDialog.querySelector('#clearSleep').hidden=!Number.isFinite(db.days[sf.elements.date.value]?.sleep);}
function openSleep(date=today()){sf.elements.date.max=today();sf.elements.date.value=date;fillSleep();sleepDialog.showModal();}sf.elements.date.onchange=fillSleep;host.querySelector('#logSleep').onclick=()=>openSleep(window.fuelDay?.()||today());host.querySelector('#logActivity').onclick=()=>window.WorkoutCalendar?.logWorkout(window.fuelDay?.()||today());sf.onsubmit=e=>{e.preventDefault();if(!sf.reportValidity()||sf.elements.date.value>today())return;const next=structuredClone(db);next.days[sf.elements.date.value]={sleep:Number(sf.elements.hours.value)};if(persist(next)){sleepDialog.close();toast('Sleep saved for '+sf.elements.date.value+'.');}};sleepDialog.querySelector('#clearSleep').onclick=()=>{const next=structuredClone(db);delete next.days[sf.elements.date.value];if(persist(next)){sleepDialog.close();toast('Sleep entry removed.');}};
document.addEventListener('fuel:date',render);document.addEventListener('calendar:changed',render);document.addEventListener('calendar:render',renderCalendar);document.addEventListener('fuel:changed',render);addEventListener('storage',e=>{if(e.key===KEY){try{const x=JSON.parse(e.newValue);if(x?.schema===1&&Array.isArray(x.targets)&&x.days)db=x;}catch{}}if([KEY,'form-fuel-calendar-v1'].includes(e.key))render();});setInterval(render,60000);render();})();
